python3 -c "
import zipfile
import json
import csv

# Load expected values
with open('/root/renewal_update.json', 'r') as f:
    data = json.load(f)

followups = []
with open('/root/followups.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        followups.append(row['item'])

# Parse output
with zipfile.ZipFile('/root/renewal_playbook_updated.hwpx', 'r') as z:
    s0 = z.read('Contents/section0.xml').decode('utf-8')
    s1 = z.read('Contents/section1.xml').decode('utf-8')

# Assertions
asserts = []

# Check all new values are present
if data['customer'] in s0: asserts.append('✓ Customer name')
else: asserts.append('✗ Customer name MISSING')

if data['owner_name'] in s0: asserts.append('✓ Owner name')
else: asserts.append('✗ Owner name MISSING')

if data['window_start'] in s0 and data['window_end'] in s0: asserts.append('✓ Renewal window (section0)')
else: asserts.append('✗ Renewal window (section0) MISSING')

if data['band'] in s0: asserts.append('✓ Pricing band')
else: asserts.append('✗ Pricing band MISSING')

if data['escalation_email'] in s0: asserts.append('✓ Escalation email')
else: asserts.append('✗ Escalation email MISSING')

if data['note'] in s0: asserts.append('✓ Pricing note')
else: asserts.append('✗ Pricing note MISSING')

# Follow-ups
for i, fu in enumerate(followups):
    if fu in s1: asserts.append(f'✓ Follow-up {i+1}')
    else: asserts.append(f'✗ Follow-up {i+1} MISSING')

# Appendix
if '이 부록 문단은 그대로 유지해야 합니다.' in s1: asserts.append('✓ Appendix preserved')
else: asserts.append('✗ Appendix MISSING')

# Old values removed
old_vals = ['Northwind', '이전담당자', '2025-04-01', '2025-04-15', 'Standard-18M', 
            'ops-old@northwind.example', '기존 메모를 새 메모로 바꾸세요.', 'old follow-up']
for v in old_vals:
    if v not in s0 and v not in s1: asserts.append(f'✓ Old value removed: {v}')
    else: asserts.append(f'✗ Old value still present: {v}')

# No linesegarray in modified paragraphs (by checking that modified paragraphs don't have it)
import xml.etree.ElementTree as ET

root0 = ET.fromstring(s0)
root1 = ET.fromstring(s1)

ns = {'hp': 'http://www.hancom.co.kr/hwpml/2010/HWPML'}

def has_linesegarray(p_elem):
    for child in p_elem:
        if child.tag == '{http://www.hancom.co.kr/hwpml/2010/HWPML}linesegarray':
            return True
    return False

# Count linesegarray - modified paragraphs should not have it
lineseg_in_modified = 0
for p in root0.findall('.//hp:p', ns):
    # Paragraphs 1-4 in section0 were modified
    pid = p.get('id')
    if pid in ['1', '2', '3', '4'] and has_linesegarray(p):
        lineseg_in_modified += 1

for p in root1.findall('.//hp:p', ns):
    pid = p.get('id')
    # Paragraphs 41-44 in section1 were modified
    if pid in ['41', '42', '43', '44'] and has_linesegarray(p):
        lineseg_in_modified += 1

if lineseg_in_modified == 0: asserts.append('✓ No linesegarray in modified paragraphs')
else: asserts.append(f'✗ Found {lineseg_in_modified} linesegarray in modified paragraphs')

# Unmodified paragraphs should retain linesegarray if they had one
# (but we can't check this easily without original)

print('Validation Results:')
for a in asserts:
    print(a)

failed = [a for a in asserts if a.startswith('✗')]
print(f'\\nTotal: {len(asserts)} checks, {len(failed)} failed')
if failed:
    for f in failed:
        print(f'  {f}')
"
